var TINH_MAP   = {"N1 - Truongdv17, Congnd15":["BNH","HNI","PTO","QNH"],"N2 - Tienvt16, Anhnt631":["NAN","QTI"],"N3 - Thikd, Ducnt84":["AGG","CTO","DNI","HCM","LDG","TNH"],"P.KD Cơ điện":["DNG"],"P.KDNLMT":["DTP","HCM"],"VHKT":["AGG","BNH","CMU","CTO","DBN","DLK","DNG","DNI","DTP","GLI","HCM","HNI","HPG","HUE","HYN","KHA","LCI","LDG","NAN","PTO","QNH","QNI","QTI","TGG","TNN","TQG","VLG"]};
